.card-container.exiting-dissolve { animation: card-dissolve 350ms forwards ease-in-out; }
@keyframes card-dissolve { to { opacity: 0; transform: translate(-50%, -50%) scale(0.95); } }

.card-container.exiting-fly-right { animation: card-fly-right 350ms forwards ease-in-out; }
@keyframes card-fly-right { to { opacity: 0; transform: translate(30%, -50%) scale(1); } }

.card-container.exiting-fly-left { animation: card-fly-left 350ms forwards ease-in-out; }
@keyframes card-fly-left { to { opacity: 0; transform: translate(-130%, -50%) scale(1); } }

