@keyframes card-fly-up-right { to { opacity: 0; transform: translate(-40%, -55%) scale(1.04) rotate(5deg); } }

.card-container.exiting-fly-through-right-left { animation: card-fly-through-right-left 350ms forwards ease-in-out; }
@keyframes card-fly-through-right-left {
