}

.card-container.exiting-fly-through-bottom-top { animation: card-fly-through-bottom-top 350ms forwards ease-in-out; }
@keyframes card-fly-through-bottom-top {
  from { opacity: 0; transform: translate(-50%, 50%) scale(1); }
  50% { opacity: 1; }
  to { opacity: 0; transform: translate(-50%, -150%) scale(1); }
}

.card-container.exiting-fly-down { animation: card-fly-down 350ms forwards ease-in-out; }
@keyframes card-fly-down { to { opacity: 0; transform: translate(-50%, 50%) scale(1); } }

.card-container.entering-from-bottom { animation: card-enter-from-bottom 350ms forwards ease-in-out; }
@keyframes card-enter-from-bottom {
  from { opacity: 0; transform: translate(-50%, 50%) scale(1); }
