.card-container.exiting-shrink-out { animation: card-shrink-out 350ms forwards ease-in-out; }
@keyframes card-shrink-out { from { opacity: 0.8; } to { opacity: 0; transform: translate(-50%, -50%) scale(0.5); } }

.card-container.exiting-up-and-grow { animation: card-exit-up-and-grow 350ms forwards ease-in-out; }
