@property --angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}

/* 流媒体边框的旋转关键帧必须取独有命名：同名 @keyframes 不合并、文档序后者胜出，
   若叫 spin 会覆盖 Tailwind animate-spin 的 rotate 关键帧（本 style 标签挂载在 body，
   晚于 head 样式表），导致卡片挂载期间全页 Loader2 加载图标静止不转 */
@keyframes streaming-border-spin {
  to { --angle: 360deg; }
}

.streaming-border-effect {
  --color-angle: 0deg;
  position: relative;
  border-color: transparent !important;
}

