/* --- 查看&调整分支点模式 / 只读模式（会员到期云端项目） --- */
/* 内容锁定：文本不可选中、不可交互（点击穿透到轮次容器，保留快捷跳转） */
.bp-locked, .bp-locked *, .ro-locked, .ro-locked * {
  user-select: none !important;
  -webkit-user-select: none !important;
}
.bp-locked *, .ro-locked * {
  pointer-events: none !important;
}
/* ToolCallDisplay 特例：锁定模式下仍允许展开/收起与滚动查看思考过程，
   但内容区（含联网搜索来源链接）与渐变遮罩保持不可交互。
   依赖 !important 规则间的特异性递增：.toolcall-passive 规则（3类）覆盖 .toolcall-shell 规则（2类）。 */
.bp-locked .toolcall-shell, .bp-locked .toolcall-shell *,
.ro-locked .toolcall-shell, .ro-locked .toolcall-shell * {
  pointer-events: auto !important;
}
.bp-locked .toolcall-shell .toolcall-passive, .bp-locked .toolcall-shell .toolcall-passive *,
.ro-locked .toolcall-shell .toolcall-passive, .ro-locked .toolcall-shell .toolcall-passive * {
  pointer-events: none !important;
}
/* 分支点以下内容半透明 */
.bp-dim-target {
  transition: opacity 350ms ease-in-out;
}
.bp-dimmed {
  opacity: 0.35;
}

/* --- 已有内容的重挂载场景（对照恢复/进入、AI 编辑退出）：
      内容入场动画以负延迟立即完成，避免看似消失又浮现 --- */
.entry-anim-suppressed .markdown-content > * {
  animation-delay: -1000ms !important;
}
.entry-anim-suppressed .new-word-fade-in {
  animation-delay: -600ms !important;
}
